"""Claude Code hook -> one JSON line per event in .local/events.jsonl.

Registered in .claude/settings.local.json for SubagentStart/Stop and Pre/PostToolUse.
Never fails the tool call: every error is swallowed and the exit code is 0.
"""
import datetime
import json
import os
import re
import sys
import time

ROOT = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
OUT = os.path.join(ROOT, ".local", "events.jsonl")
CLIP = 600  # chars of stdout/stderr kept per event


def rel(p):
    try:
        return os.path.relpath(p, ROOT).replace("\\", "/")
    except Exception:
        return p


def current_step():
    try:
        with open(os.path.join(ROOT, "PROGRESS.md"), encoding="utf-8") as f:
            m = re.search(r"^## Current step: (\d+)", f.read(), re.M)
            return int(m.group(1)) if m else None
    except Exception:
        return None


def prompt_of(d):
    """First user line of the subagent transcript; written ~100 ms before SubagentStart fires."""
    tp = d.get("agent_transcript_path")
    if not tp:
        base = os.path.dirname(d.get("transcript_path", ""))
        tp = os.path.join(base, d.get("session_id", ""), "subagents", "agent-%s.jsonl" % d.get("agent_id"))
    for _ in range(6):
        try:
            with open(tp, encoding="utf-8") as f:
                first = json.loads(f.readline())
            c = first.get("message", {}).get("content")
            if isinstance(c, list):
                c = " ".join(x.get("text", "") for x in c if isinstance(x, dict))
            return c or ""
        except Exception:
            time.sleep(0.05)
    return ""


def lane_of(text):
    m = re.match(r"\s*Lane ([A-Z])\b(?:\s*[—–-]\s*([^\n.]{0,60}))?", text or "")
    return (m.group(1), (m.group(2) or "").strip()) if m else (None, "")


def tool_fields(tool, ti):
    e = {}
    if tool == "Bash":
        e["cmd"] = (ti.get("command") or "")[:400]
        if ti.get("description"):
            e["desc"] = ti["description"][:120]
    elif tool in ("Edit", "Write", "Read", "NotebookEdit", "MultiEdit"):
        e["file"] = rel(ti.get("file_path") or ti.get("notebook_path") or "")
    elif tool in ("Grep", "Glob"):
        e["pattern"] = (ti.get("pattern") or "")[:120]
        if ti.get("path"):
            e["file"] = rel(ti["path"])
    elif tool == "Agent":
        e["desc"] = (ti.get("description") or "")[:120]
        e["subagent"] = ti.get("subagent_type") or "general-purpose"
        e["lane"], e["title"] = lane_of(ti.get("prompt") or "")
    return e


def main():
    d = json.load(sys.stdin)
    ev = d.get("hook_event_name")
    e = {
        "ts": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z",
        "session": (d.get("session_id") or "")[:8],
        "agent": d.get("agent_id") or "main",
        "type": d.get("agent_type") or "main",
        "step": current_step(),
    }
    if ev == "SubagentStart":
        e["ev"] = "agent.start"
        e["lane"], e["title"] = lane_of(prompt_of(d))
    elif ev == "SubagentStop":
        e["ev"] = "agent.stop"
    elif ev == "PreToolUse":
        e["ev"] = "tool.pre"
        e["tool"] = d.get("tool_name")
        e["id"] = d.get("tool_use_id")
        e.update(tool_fields(e["tool"], d.get("tool_input") or {}))
    elif ev == "PostToolUse":
        e["ev"] = "tool.post"
        e["tool"] = d.get("tool_name")
        e["id"] = d.get("tool_use_id")
        e["ms"] = d.get("duration_ms")
        tr = d.get("tool_response") or {}
        if isinstance(tr, dict):
            if tr.get("stdout"):
                e["out"] = tr["stdout"][-CLIP:]
            if tr.get("stderr"):
                e["err"] = tr["stderr"][-CLIP:]
            if tr.get("interrupted"):
                e["interrupted"] = True
        elif isinstance(tr, str) and tr:
            e["out"] = tr[-CLIP:]
    else:
        return
    with open(OUT, "a", encoding="utf-8") as f:
        f.write(json.dumps({k: v for k, v in e.items() if v not in (None, "")}) + "\n")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        pass
    sys.exit(0)

