#!/usr/bin/env python3
"""Build board server: the one brain over PROGRESS.md, .local/log.md, .local/events.jsonl and the transcripts.
Stdlib only. State lives in the files; this server owns nothing (model.json is a derived cache for the snapshot).
Run: python .local/board.py [port]   (default 8099, binds 127.0.0.1)     python .local/board.py --check
Contract: .local/board-spec.md
"""
import json
import os
import re
import sys
import threading
import time
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, unquote

ROOT = Path(__file__).resolve().parent.parent
LOCAL = ROOT / ".local"
PROGRESS_MD = ROOT / "PROGRESS.md"
LOG_MD = LOCAL / "log.md"
EVENTS_JSONL = LOCAL / "events.jsonl"
MODEL_JSON = LOCAL / "model.json"
PAGE = LOCAL / "progress.html"
CTX_WINDOW = 200_000  # every model the crew uses runs a 200k window; the % is against that, not a per-model table
LIVE_AGENT_S, LIVE_MAIN_S = 30 * 60, 10 * 60
DISCONNECTS = (BrokenPipeError, ConnectionAbortedError, ConnectionResetError)

# ---------- time ----------

def utcnow():
    return datetime.now(timezone.utc)


def iso(dt, ms=True):
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond // 1000:03d}Z" if ms else dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_ts(s):
    if not s:
        return None
    try:
        return datetime.strptime(s[:19], "%Y-%m-%dT%H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def ago(dt, now):
    if not dt:
        return "?"
    s = max(0, int((now - dt).total_seconds()))
    return f"{s}s ago" if s < 60 else f"{s // 60}m ago" if s < 3600 else f"{s / 3600:.1f}h ago"


def dur(ms):
    if ms is None:
        return ""
    s = ms // 1000
    return f"{s}s" if s < 60 else f"{s // 60}m {s % 60}s" if s < 3600 else f"{s / 3600:.1f}h"


def hms(s):
    return s[11:19] if s else ""


def short_model(m):
    if not m:
        return "?"
    m = m.replace("claude-", "")
    m = re.sub(r"-\d{8}$", "", m)
    parts = m.split("-")
    return parts[0] + (" " + ".".join(parts[1:]) if len(parts) > 1 else "")


# ---------- files ----------

def read_text(path):
    try:
        return path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return ""


def snap(path):
    try:
        st = path.stat()
        return (st.st_mtime, st.st_size)
    except FileNotFoundError:
        return (0, 0)


def tail_events(offset):
    """Complete JSON lines since offset, and the offset to resume from (stops at the last newline)."""
    try:
        with open(EVENTS_JSONL, "rb") as f:
            f.seek(offset)
            chunk = f.read()
    except FileNotFoundError:
        return [], offset
    nl = chunk.rfind(b"\n")
    if nl == -1:
        return [], offset
    objs = []
    for line in chunk[: nl + 1].decode("utf-8", "replace").splitlines():
        line = line.strip()
        if line:
            try:
                objs.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return objs, offset + nl + 1


# ---------- plan ----------

def parse_plan(md):
    status = re.search(r"^\*\*Status \(([^)]+)\):\*\*\s*(.+)$", md, re.M)
    plan = {"status": {"date": status.group(1), "text": status.group(2).strip()} if status else {"date": "", "text": ""},
            "milestones": [], "stories": []}
    sections = re.split(r"^(?=## )", md, flags=re.M)
    cur_num = None
    for sec in sections:
        head = sec.split("\n", 1)[0]
        body = sec.split("\n", 1)[1] if "\n" in sec else ""
        if head.startswith("## Milestones"):
            for m in re.finditer(r"^### (M\d+) — ([^\n]+?)\s*(✅|🔶)?\s*$((?:\n(?!###)[^\n]*)*)", body, re.M):
                steps = []
                for s in re.finditer(r"^- \[([ x])\] (\d\d) (.+)$", m.group(4), re.M):
                    title = s.group(3)
                    current = "**current**" in title
                    commit = re.search(r"`([0-9a-f]{7,40})`", title)
                    title = re.sub(r"\s*\(`[0-9a-f]{7,40}`\)|\s*—\s*\*\*current\*\*", "", title).strip()
                    if current:
                        cur_num = int(s.group(2))
                    steps.append({"num": s.group(2), "title": title, "done": s.group(1) == "x", "current": current,
                                  "commit": commit.group(1) if commit else None})
                plan["milestones"].append({"id": m.group(1), "title": m.group(2).strip(), "done": all(x["done"] for x in steps) and bool(steps), "steps": steps})
        elif head.startswith("## Current step:") or head.startswith("## Sandbox:"):
            is_step = head.startswith("## Current step:")
            if is_step:
                hm = re.match(r"## Current step: (\d+)\s*—\s*(.+)$", head)
                num, title = int(hm.group(1)), hm.group(2).strip()
                sid = f"step-{num}"
            else:
                num, title = None, head[len("## Sandbox:"):].strip()
                sid = "sandbox-%d" % (1 + sum(1 for s in plan["stories"] if s["kind"] == "sandbox"))
            dw = re.search(r"^Done when:\s*(.*?)(?=\n\s*\n|\Z)", body, re.S | re.M)
            done_when = re.sub(r"\s+", " ", dw.group(1)).strip() if dw else ""
            first_lane = body.find("### Lane")
            pre = body[: first_lane if first_lane >= 0 else len(body)]
            if dw:
                pre = pre.replace(dw.group(0), "", 1)
            decisions = pre.strip()
            lanes = []
            for lm in re.finditer(r"^### Lane ([A-Z]) — ([^\n]+)$((?:\n(?!###)[^\n]*)*)", body, re.M):
                parts = [p.strip() for p in lm.group(2).split("·")]
                tags = parts[1:]
                mode = next((t for t in tags if t in ("serial", "parallel", "inline", "optional")), None)
                lb = lm.group(3)
                tm = re.search(r"^_touches: (.+)_$", lb, re.M)
                tasks, stack = [], []
                for t in re.finditer(r"^( *)- \[([ x])\] (\S+) (.+)$", lb, re.M):
                    depth = len(t.group(1)) // 2
                    node = {"key": t.group(3), "text": t.group(4).strip(), "depth": depth, "ticked": t.group(2) == "x", "children": []}
                    while stack and stack[-1]["depth"] >= depth:
                        stack.pop()
                    (stack[-1]["children"] if stack else tasks).append(node)
                    stack.append(node)
                lanes.append({"letter": lm.group(1), "name": parts[0], "tags": tags, "mode": mode,
                              "touches": tm.group(1).strip() if tm else "", "tasks": tasks})
            plan["stories"].append({"id": sid, "kind": "step" if is_step else "sandbox", "num": num, "title": title,
                                    "doneWhen": done_when, "decisions": decisions, "lanes": lanes})
    steps = [s for m in plan["milestones"] for s in m["steps"]]
    plan["steps"] = {"done": sum(1 for s in steps if s["done"]), "total": len(steps), "current": cur_num}
    plan["stories"].sort(key=lambda s: 0 if s["kind"] == "step" else 1)
    return plan


def parse_log(md):
    """{section name: [lines]} — sections are '## step 16', '## sandbox', ..."""
    out, cur = {}, None
    for line in md.splitlines():
        if line.startswith("## "):
            cur = line[3:].strip().lower()
            out.setdefault(cur, [])
            continue
        m = re.match(r"^- (\S+) · ([^·]+?) · ([^·]+?) · (start|done|blocked|note) · ?(.*)$", line)
        if m and cur is not None:
            out[cur].append({"ts": m.group(1), "agent": m.group(2).strip(), "key": m.group(3).strip(), "status": m.group(4), "note": m.group(5).strip()})
    return out


def walk(tasks):
    for t in tasks:
        yield t
        yield from walk(t["children"])


# ---------- usage (transcripts) ----------

class Usage:
    """Tails every transcript the events name; per agent: model, calls, output tokens, current context."""

    def __init__(self):
        self.paths = {}    # key -> path
        self.offsets = {}  # path -> byte offset
        self.seen = {}     # path -> set(message.id)
        self.stats = {}    # key -> dict
        self.version = 0
        self.lock = threading.Lock()

    def register(self, key, path):
        if path and key not in self.paths:
            self.paths[key] = path

    def poll(self):
        changed = False
        for key, path in list(self.paths.items()):
            try:
                size = os.path.getsize(path)
            except OSError:
                continue
            off = self.offsets.get(path, 0)
            if size <= off:
                continue
            with open(path, "rb") as f:
                f.seek(off)
                chunk = f.read()
            nl = chunk.rfind(b"\n")
            if nl == -1:
                continue
            self.offsets[path] = off + nl + 1
            seen = self.seen.setdefault(path, set())
            st = self.stats.setdefault(key, {"model": None, "calls": 0, "out": 0, "ctx": 0, "lastTs": None})
            for line in chunk[: nl + 1].decode("utf-8", "replace").splitlines():
                if '"assistant"' not in line:
                    continue
                try:
                    x = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if x.get("type") != "assistant":
                    continue
                m = x.get("message") or {}
                u = m.get("usage")
                if not u:
                    continue
                mid = m.get("id")
                if mid in seen:
                    continue
                seen.add(mid)
                st["model"] = m.get("model") or st["model"]
                st["calls"] += 1
                st["out"] += u.get("output_tokens", 0) or 0
                st["ctx"] = (u.get("input_tokens", 0) or 0) + (u.get("cache_creation_input_tokens", 0) or 0) + (u.get("cache_read_input_tokens", 0) or 0)
                st["lastTs"] = x.get("timestamp") or st["lastTs"]
                changed = True
        if changed:
            with self.lock:
                self.version += 1
        return changed


# ---------- model ----------

class Board:
    def __init__(self):
        self.lock = threading.Lock()
        self.snaps = {}
        self.plan = self.log = None
        self.events = []
        self.usage = Usage()
        self.version = 0
        self._usage_seen = -1
        self._model = None

    def refresh(self):
        """Re-read whichever file changed; bump version if anything did."""
        with self.lock:
            changed = False
            for name, path in (("plan", PROGRESS_MD), ("log", LOG_MD), ("events", EVENTS_JSONL)):
                s = snap(path)
                if s != self.snaps.get(name):
                    self.snaps[name] = s
                    changed = True
                    if name == "plan":
                        self.plan = parse_plan(read_text(path))
                    elif name == "log":
                        self.log = parse_log(read_text(path))
                    else:
                        self.events = []
                        for line in read_text(path).splitlines():
                            try:
                                self.events.append(json.loads(line))
                            except json.JSONDecodeError:
                                continue
                        for e in self.events:
                            if e.get("transcript"):
                                self.usage.register(e["agent"] if e["agent"] != "main" else f"main@{e.get('session', '')}", e["transcript"])
            if self.usage.version != self._usage_seen:
                self._usage_seen = self.usage.version
                changed = True
            if changed:
                self.version += 1
                self._model = None
        return changed

    def model(self):
        self.refresh()
        with self.lock:
            if self._model is None:
                self._model = self._build()
            return self._model

    def _build(self):
        now = utcnow()
        plan = self.plan or parse_plan("")
        stories = json.loads(json.dumps(plan["stories"]))  # deep copy; the cached plan stays pristine
        cur = plan["steps"]["current"]
        events = [e for e in self.events if e.get("step") == cur or e.get("session") == "selftest"] if cur else []
        events = [e for e in events if e.get("session") != "selftest"]

        lane_story = {}
        for s in stories:
            for l in s["lanes"]:
                lane_story.setdefault(l["letter"], (s, l))

        # agents
        agents, dispatches = {}, {}
        for e in events:
            sess = e.get("session", "")
            key = e["agent"] if e["agent"] != "main" else f"main@{sess}"
            a = agents.get(key)
            if a is None:
                a = agents[key] = {"id": key, "type": e.get("type", "agent"), "session": sess, "lane": None, "story": None, "title": "",
                                   "start": e["ts"], "stop": None, "live": False, "lastTs": e["ts"], "lastTool": None, "last": "",
                                   "tools": 0, "errors": 0, "box": None, "model": None, "calls": 0, "out": 0, "ctx": 0, "ctxPct": 0}
                if e["agent"] == "main" and "C" in lane_story:
                    a["lane"] = "C"
            a["lastTs"] = e["ts"]
            ev = e.get("ev")
            if ev == "agent.start":
                a["start"] = e["ts"]
                a["lane"] = e.get("lane") or a["lane"]
                a["title"] = e.get("title") or a["title"]
                if not a["lane"]:
                    for d in dispatches.get(sess, []):
                        if not d.get("claimed") and d["ts"] <= e["ts"]:
                            d["claimed"] = True
                            a["lane"], a["title"] = d["lane"], d.get("title", "")
                            break
            elif ev == "agent.stop":
                a["stop"] = e["ts"]
            elif ev == "tool.pre":
                a["tools"] += 1
                a["lastTool"] = e.get("tool")
                a["last"] = e.get("cmd") or e.get("file") or e.get("pattern") or e.get("desc") or ""
                if e.get("tool") == "Agent" and e.get("lane"):
                    dispatches.setdefault(sess, []).append({"ts": e["ts"], "lane": e["lane"], "title": e.get("title", "")})
            elif ev == "tool.post" and (e.get("err") or e.get("interrupted")):
                a["errors"] += 1
        for key, a in agents.items():
            st = self.usage.stats.get(key)
            if st:
                a.update({"model": st["model"], "calls": st["calls"], "out": st["out"], "ctx": st["ctx"], "ctxPct": round(100 * st["ctx"] / CTX_WINDOW)})
            last = parse_ts(a["lastTs"])
            age = (now - last).total_seconds() if last else 1e9
            a["live"] = (a["stop"] is None) and age < (LIVE_MAIN_S if key.startswith("main@") else LIVE_AGENT_S)
            if a["lane"] in lane_story:
                a["story"] = lane_story[a["lane"]][0]["id"]

        # tasks
        for s in stories:
            section = f"step {s['num']}" if s["kind"] == "step" else "sandbox"
            lines = (self.log or {}).get(section, [])
            by_key = {}
            for ln in lines:
                by_key.setdefault(ln["key"], []).append(ln)
            # windows per label: start line -> until the label's next start/done/blocked line
            windows = []  # (label, key, t0, t1)
            per_label = {}
            for ln in lines:
                if ln["status"] in ("start", "done", "blocked"):
                    per_label.setdefault(ln["agent"], []).append(ln)
            for label, lns in per_label.items():
                for i, ln in enumerate(lns):
                    if ln["status"] == "start":
                        t1 = lns[i + 1]["ts"] if i + 1 < len(lns) else None
                        windows.append((label, ln["key"], ln["ts"], t1))
            for l in s["lanes"]:
                lane_agents = [a for a in agents.values() if a["lane"] == l["letter"]]
                l["agents"] = [a["id"] for a in lane_agents]
                live = [a for a in lane_agents if a["live"]]
                l["live"] = live[-1]["id"] if live else None
                for t in walk(l["tasks"]):
                    tl = by_key.get(t["key"], [])
                    t["log"] = tl
                    last = tl[-1] if tl else None
                    t["note"] = last["note"] if last and last["note"] else None
                    own = "done" if t["ticked"] else ("reported" if last and last["status"] == "done" else "blocked" if last and last["status"] == "blocked" else "doing" if last else "todo")
                    t["status"] = own
                    starts = [x for x in tl if x["status"] == "start"]
                    dones = [x for x in tl if x["status"] == "done"]
                    label = (starts or dones or [{"agent": None}])[0]["agent"]
                    t["agent"] = label
                    cands = [a for a in lane_agents if a["type"] == label]
                    t["agentId"] = cands[-1]["id"] if cands else None
                    t["started"] = starts[0]["ts"] if starts else (l["live"] and own == "doing" and agents[l["live"]]["start"]) or None
                    t["finished"] = dones[-1]["ts"] if dones else None
                    t0, t1 = parse_ts(t["started"]), parse_ts(t["finished"])
                    t["ms"] = int((t1 - t0).total_seconds() * 1000) if t0 and t1 else int((now - t0).total_seconds() * 1000) if t0 and own == "doing" else None
                    tools = errors = 0
                    for (wl, wk, w0, w1) in windows:
                        if wk != t["key"]:
                            continue
                        for e in events:
                            if e.get("type") != wl or e["ts"] < w0 or (w1 and e["ts"] >= w1):
                                continue
                            akey = e["agent"] if e["agent"] != "main" else f"main@{e.get('session', '')}"
                            if agents.get(akey, {}).get("lane") != l["letter"]:
                                continue
                            if e["ev"] == "tool.pre":
                                tools += 1
                            elif e["ev"] == "tool.post" and (e.get("err") or e.get("interrupted")):
                                errors += 1
                    t["tools"], t["errors"] = tools, errors
                # roll-up, children first
                def roll(t):
                    for c in t["children"]:
                        roll(c)
                    if t["children"] and not t["ticked"]:
                        cs = [c["status"] for c in walk(t["children"])]
                        if "blocked" in cs:
                            t["status"] = "blocked"
                        elif "doing" in cs or "reported" in cs:
                            t["status"] = "doing"
                for t in l["tasks"]:
                    roll(t)
                l["counts"] = counts(walk(l["tasks"]))
            s["counts"] = counts(t for l in s["lanes"] for t in walk(l["tasks"]))
            # the agent's open box
            for (label, key, t0, t1) in windows:
                if t1 is None:
                    for a in agents.values():
                        if a["type"] == label and a["lane"] and any(l["letter"] == key[0] for l in s["lanes"]) and a["lane"] == key[0]:
                            a["box"] = key
        for a in agents.values():
            a["tools"] = a["tools"]
        sessions = sorted({a["session"] for a in agents.values() if a["session"]})
        totals = {"agents": len(agents), "live": sum(1 for a in agents.values() if a["live"]),
                  "tools": sum(a["tools"] for a in agents.values()), "errors": sum(a["errors"] for a in agents.values()),
                  "out": sum(a["out"] for a in agents.values()), "sessions": sessions}
        return {"now": iso(now), "status": plan["status"], "steps": plan["steps"], "milestones": plan["milestones"],
                "stories": stories, "agents": agents, "totals": totals}


def counts(tasks):
    c = {"done": 0, "reported": 0, "doing": 0, "blocked": 0, "todo": 0, "total": 0}
    for t in tasks:
        c[t["status"]] += 1
        c["total"] += 1
    return c


# ---------- text views ----------

def agent_tag(a):
    return f"{a['type']}@{a['id'][-5:]}" + (f" ({short_model(a['model'])}, ctx {a['ctxPct']}%)" if a.get("model") else "")


def text_summary(m):
    now = parse_ts(m["now"])
    out = [f"{m['status']['text']} (as of {m['status']['date']})"]
    blocked, reported, nxt = [], [], []
    for s in m["stories"]:
        head = f"step {s['num']}" if s["kind"] == "step" else f"sandbox '{s['title']}'"
        c = s["counts"]
        out.append(f"{head} — {s['title'] if s['kind'] == 'step' else ''} · {c['done']}/{c['total']} done, {c['reported']} reported, {c['doing']} doing, {c['blocked']} blocked")
        for l in s["lanes"]:
            c = l["counts"]
            line = f"  lane {l['letter']} {l['name']} · {l['mode'] or '-'} · {c['done']}/{c['total']}"
            if l["live"]:
                a = m["agents"][l["live"]]
                line += f" · live {agent_tag(a)}" + (f" on {a['box']}" if a["box"] else "") + f" · last: {a['last'][:80]} ({ago(parse_ts(a['lastTs']), now)})"
            out.append(line)
            for t in walk(l["tasks"]):
                if t["status"] == "blocked":
                    blocked.append(f"{t['key']} ({t['note'] or 'no reason logged'})")
                elif t["status"] == "reported":
                    reported.append(t["key"])
            todo = [t["key"] for t in walk(l["tasks"]) if t["status"] == "todo" and not t["children"]]
            if todo:
                nxt.append(todo[0])
    out.append("blocked: " + (", ".join(blocked) or "—"))
    out.append("reported (awaiting tick): " + (", ".join(reported) or "—"))
    out.append("next: " + (", ".join(nxt) or "—"))
    live = [a for a in m["agents"].values() if a["live"]]
    out.append(f"agents live: {len(live)} · tool calls: {m['totals']['tools']} · errors: {m['totals']['errors']} · tokens out: {m['totals']['out']}")
    return "\n".join(out[:60])


def text_next(m, n=3):
    out = []
    for s in m["stories"]:
        out.append(f"{'step ' + str(s['num']) if s['kind'] == 'step' else 'sandbox'} — done when: {s['doneWhen']}")
        for l in s["lanes"]:
            todo = [t for t in walk(l["tasks"]) if t["status"] == "todo" and not t["children"]][:n]
            if todo:
                out.append(f"lane {l['letter']} {l['name']} ({l['mode'] or '-'}) touches {l['touches']}")
                for t in todo:
                    out.append(f"  {t['key']} {t['text']}")
    return "\n".join(out) or "nothing to do"


def text_wip(m, events):
    now = parse_ts(m["now"])
    out = []
    for a in sorted(m["agents"].values(), key=lambda a: a["start"]):
        if not a["live"]:
            continue
        out.append(f"{agent_tag(a)} · lane {a['lane'] or '?'} {a['title']} · box {a['box'] or '-'} · up {ago(parse_ts(a['start']), now).replace(' ago', '')} · {a['tools']} tools, {a['errors']} errors, {a['out']} tokens out · last event {ago(parse_ts(a['lastTs']), now)}")
        mine = [e for e in events if (e["agent"] if e["agent"] != "main" else f"main@{e.get('session', '')}") == a["id"] and e["ev"] == "tool.pre"][-3:]
        posts = {e["id"]: e for e in events if e["ev"] == "tool.post"}
        for e in mine:
            p = posts.get(e.get("id"), {})
            out.append(f"    {hms(e['ts'])} {e.get('tool')} {dur(p.get('ms'))}{' ERR' if p.get('err') or p.get('interrupted') else ''} {(e.get('cmd') or e.get('file') or e.get('pattern') or '')[:100]}")
    return "\n".join(out) or "no agent is live"


def find_lane(m, letter):
    for s in m["stories"]:
        for l in s["lanes"]:
            if l["letter"] == letter:
                return s, l
    return None, None


def find_task(m, key):
    for s in m["stories"]:
        for l in s["lanes"]:
            for t in walk(l["tasks"]):
                if t["key"] == key:
                    return s, l, t
    return None, None, None


def task_line(t, m):
    a = m["agents"].get(t["agentId"]) if t["agentId"] else None
    bits = [f"{'  ' * t['depth']}[{'x' if t['status'] == 'done' else t['status'][0]}] {t['key']} {t['text']}"]
    if t["agent"]:
        bits.append(t["agent"] + (f" ({short_model(a['model'])})" if a and a.get("model") else ""))
    if t["started"]:
        bits.append(hms(t["started"]))
    if t["ms"] is not None:
        bits.append(dur(t["ms"]))
    if t["tools"]:
        bits.append(f"{t['tools']} tools" + (f", {t['errors']} errors" if t["errors"] else ""))
    return " · ".join(bits)


def text_lane(m, letter):
    s, l = find_lane(m, letter)
    if not l:
        return None
    out = [f"lane {l['letter']} {l['name']} · {' · '.join(l['tags'])}", f"touches: {l['touches']}",
           f"{l['counts']['done']}/{l['counts']['total']} done · live: {agent_tag(m['agents'][l['live']]) if l['live'] else '-'}"]
    out += [task_line(t, m) for t in walk(l["tasks"])]
    return "\n".join(out)


def text_task(m, key, events):
    s, l, t = find_task(m, key)
    if not t:
        return None
    crumbs = [f"step {s['num']}" if s["kind"] == "step" else f"sandbox {s['title']}", f"lane {l['letter']}"]
    parts = key.split(".")
    crumbs += [".".join(parts[:i]) for i in range(1, len(parts))]
    a = m["agents"].get(t["agentId"]) if t["agentId"] else None
    out = [" › ".join(crumbs + [key]), f"status: {t['status']}", t["text"],
           f"agent: {t['agent'] or '-'}" + (f" · {agent_tag(a)}" if a else ""),
           f"started: {hms(t['started'])} · finished: {hms(t['finished'])} · {dur(t['ms'])} · {t['tools']} tools, {t['errors']} errors"]
    for ln in t["log"]:
        out.append(f"  {hms(ln['ts'])} {ln['agent']} {ln['status']} {ln['note']}")
    if t["children"]:
        out.append("children:")
        out += ["  " + task_line(c, m) for c in walk(t["children"])]
    if a:
        starts = [x for x in t["log"] if x["status"] == "start"]
        if starts:
            t0 = starts[0]["ts"]
            t1 = next((x["ts"] for x in t["log"] if x["ts"] > t0 and x["status"] in ("done", "blocked")), None)
            mine = [e for e in events if e["ev"] == "tool.pre" and (e["agent"] if e["agent"] != "main" else f"main@{e.get('session', '')}") == a["id"] and e["ts"] >= t0 and (not t1 or e["ts"] < t1)][-20:]
            posts = {e["id"]: e for e in events if e["ev"] == "tool.post"}
            if mine:
                out.append("tool events:")
            for e in mine:
                p = posts.get(e.get("id"), {})
                out.append(f"  {hms(e['ts'])} {e.get('tool')} {dur(p.get('ms'))}{' ERR' if p.get('err') or p.get('interrupted') else ''} {(e.get('cmd') or e.get('file') or e.get('pattern') or '')[:100]}")
    return "\n".join(out)


def text_agent(m, ident, events):
    a = next((a for a in m["agents"].values() if a["id"] == ident or a["id"].endswith(ident)), None)
    if not a:
        return None
    now = parse_ts(m["now"])
    out = [f"{agent_tag(a)} · session {a['session']} · {'live' if a['live'] else 'stopped ' + hms(a['stop'] or '')}",
           f"lane {a['lane'] or '?'} {a['title']} · box {a['box'] or '-'} · started {hms(a['start'])} ({ago(parse_ts(a['start']), now)})",
           f"model {a['model'] or '?'} · {a['calls']} calls · {a['out']} tokens out · ctx {a['ctx']} ({a['ctxPct']}%)",
           f"{a['tools']} tools · {a['errors']} errors · last: {a['last'][:120]}"]
    mine = [e for e in events if (e["agent"] if e["agent"] != "main" else f"main@{e.get('session', '')}") == a["id"] and e["ev"] in ("tool.pre", "agent.start", "agent.stop")][-30:]
    posts = {e["id"]: e for e in events if e["ev"] == "tool.post"}
    for e in mine:
        p = posts.get(e.get("id"), {})
        out.append(f"  {hms(e['ts'])} {e.get('tool') or e['ev']} {dur(p.get('ms'))}{' ERR' if p.get('err') or p.get('interrupted') else ''} {(e.get('cmd') or e.get('file') or e.get('pattern') or e.get('lane') or '')[:100]}")
    return "\n".join(out)


def tick(key, done):
    md = read_text(PROGRESS_MD)
    pat = re.compile(r"^(\s*- \[)([ x])(\] " + re.escape(key) + r" )", re.M)
    if not pat.search(md):
        return None
    md = pat.sub(lambda mm: mm.group(1) + ("x" if done else " ") + mm.group(3), md, count=1)
    plan = parse_plan(md)
    step = next((s for s in plan["stories"] if s["kind"] == "step"), None)
    if step:
        boxes = [t for l in step["lanes"] for t in walk(l["tasks"])]
        n, tot = sum(1 for t in boxes if t["ticked"]), len(boxes)
        md = re.sub(r"\(\d+ / \d+ boxes\)", f"({n} / {tot} boxes)", md, count=1)
    with open(PROGRESS_MD, "w", encoding="utf-8", newline="\n") as f:
        f.write(md)
    return True


# ---------- http ----------

BOARD = Board()


def write_model_json(m):
    tmp = MODEL_JSON.with_suffix(".tmp")
    tmp.write_text(json.dumps(m), encoding="utf-8")
    os.replace(tmp, MODEL_JSON)


def background():
    """Usage polling + model.json dump; the SSE handlers only read."""
    written = -1
    while True:
        try:
            BOARD.usage.poll()
            BOARD.refresh()
            if BOARD.version != written:
                write_model_json(BOARD.model())
                written = BOARD.version
        except Exception:
            pass
        time.sleep(2)


class Handler(BaseHTTPRequestHandler):
    server_version = "BoardHTTP/2.0"

    def log_message(self, fmt, *args):
        pass

    def _send(self, status, body, content_type="text/plain; charset=utf-8"):
        data = body.encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)
        except DISCONNECTS:
            pass

    def _text_or_json(self, text, data, q):
        if q.get("format", [""])[0] == "json":
            self._send(200, json.dumps(data), "application/json; charset=utf-8")
        else:
            self._send(200, text if text is not None else "not found")

    def do_GET(self):
        path, _, qs = self.path.partition("?")
        q = parse_qs(qs)
        path = unquote(path)
        if path in ("/", "/.local/progress.html"):
            return self._send(200, read_text(PAGE), "text/html; charset=utf-8")
        if path == "/api/stream":
            return self._stream()
        if path in ("/progress.md", "/log.md", "/events.jsonl", "/model.json"):
            src = {"/progress.md": PROGRESS_MD, "/log.md": LOG_MD, "/events.jsonl": EVENTS_JSONL, "/model.json": MODEL_JSON}[path]
            return self._send(200, read_text(src), "application/json" if path == "/model.json" else "text/plain; charset=utf-8")
        m = BOARD.model()
        events = BOARD.events
        if path == "/api/model":
            return self._send(200, json.dumps(m), "application/json; charset=utf-8")
        if path == "/api/state":
            return self._send(200, json.dumps({"model": m, "events": events[-5000:], "now": m["now"]}), "application/json; charset=utf-8")
        if path == "/api/summary":
            return self._text_or_json(text_summary(m), {"status": m["status"], "steps": m["steps"], "totals": m["totals"], "stories": [{"id": s["id"], "counts": s["counts"], "lanes": [{"letter": l["letter"], "counts": l["counts"], "live": l["live"]} for l in s["lanes"]]} for s in m["stories"]]}, q)
        if path == "/api/next":
            n = int(q.get("n", ["3"])[0])
            return self._text_or_json(text_next(m, n), [{"lane": l["letter"], "tasks": [t for t in walk(l["tasks"]) if t["status"] == "todo" and not t["children"]][:n]} for s in m["stories"] for l in s["lanes"]], q)
        if path == "/api/wip":
            return self._text_or_json(text_wip(m, events), [a for a in m["agents"].values() if a["live"]], q)
        if path.startswith("/api/lane/"):
            s, l = find_lane(m, path[len("/api/lane/"):])
            return self._text_or_json(text_lane(m, path[len("/api/lane/"):]), l, q) if l else self._send(404, "no such lane")
        if path.startswith("/api/task/"):
            key = path[len("/api/task/"):]
            s, l, t = find_task(m, key)
            return self._text_or_json(text_task(m, key, events), t, q) if t else self._send(404, "no such task")
        if path.startswith("/api/agent/"):
            ident = path[len("/api/agent/"):]
            a = next((a for a in m["agents"].values() if a["id"] == ident or a["id"].endswith(ident)), None)
            return self._text_or_json(text_agent(m, ident, events), a, q) if a else self._send(404, "no such agent")
        self._send(404, "not found")

    def do_POST(self):
        path = self.path.split("?", 1)[0]
        length = int(self.headers.get("Content-Length", 0) or 0)
        raw = self.rfile.read(length) if length else b""
        ctype = (self.headers.get("Content-Type") or "").lower()
        if path == "/api/log":
            if "json" in ctype:
                try:
                    obj = json.loads(raw.decode("utf-8"))
                except json.JSONDecodeError:
                    return self._send(400, "bad json")
                line = f"- {iso(utcnow(), ms=False)} · {obj.get('agent', '')} · {obj.get('key', '')} · {obj.get('status', '')} · {obj.get('note', '')}"
            else:
                line = raw.decode("utf-8").strip()
                if not line.startswith("- "):
                    line = "- " + line
            with open(LOG_MD, "a", encoding="utf-8") as f:
                f.write(line + "\n")
            return self._send(204, "")
        if path == "/api/tick":
            try:
                obj = json.loads(raw.decode("utf-8"))
            except json.JSONDecodeError:
                return self._send(400, "bad json")
            if not tick(obj.get("key", ""), bool(obj.get("done", True))):
                return self._send(404, "no such key")
            return self._send(200, text_summary(BOARD.model()))
        self._send(404, "not found")

    def _sse(self, event, data):
        self.wfile.write(f"event: {event}\ndata: {data}\n\n".encode("utf-8"))
        self.wfile.flush()

    def _stream(self):
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "keep-alive")
        self.end_headers()
        sent_version = BOARD.version
        events_offset = snap(EVENTS_JSONL)[1]
        last_ping = last_model = time.monotonic()
        try:
            while True:
                BOARD.refresh()
                st = snap(EVENTS_JSONL)
                if st[1] < events_offset:
                    events_offset = 0  # truncated/rotated: replay from the start
                objs, events_offset = tail_events(events_offset)
                if objs:
                    self._sse("events", json.dumps(objs))
                m = None
                if BOARD.version != sent_version and time.monotonic() - last_model > 0.3:
                    m = BOARD.model()
                elif time.monotonic() - last_model > 5 and any(a["live"] for a in BOARD.model()["agents"].values()):
                    m = BOARD.model()
                if m is not None:
                    self._sse("model", json.dumps(m))
                    sent_version, last_model = BOARD.version, time.monotonic()
                if time.monotonic() - last_ping >= 15:
                    self._sse("ping", "{}")
                    last_ping = time.monotonic()
                time.sleep(0.25)
        except DISCONNECTS:
            return


def check():
    m = BOARD.model()
    step = next(s for s in m["stories"] if s["kind"] == "step")
    assert len(step["lanes"]) == 6, [l["letter"] for l in step["lanes"]]
    sb = [s for s in m["stories"] if s["kind"] == "sandbox"]
    assert sb and any(t["depth"] == 3 for l in sb[0]["lanes"] for t in walk(l["tasks"])), "sandbox depth"
    assert find_task(m, "X1.2")[2]["status"] == "done"
    print(text_summary(m))
    print("--- check ok")


if __name__ == "__main__":
    if "--check" in sys.argv:
        BOARD.usage.poll()
        check()
        sys.exit(0)
    port = int(sys.argv[1]) if len(sys.argv) > 1 and sys.argv[1].isdigit() else 8099
    threading.Thread(target=background, daemon=True).start()
    httpd = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    print(f"board.py listening on http://127.0.0.1:{port}")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
